css.value:
* { 
    margin: 0;
    font-family: var(--Typography-Font--now-heading--font-family,cabin);
    font-size: var(--Typography-Size-Display-header-secondary,20px);
    font-style: normal;
    line-height: normal;
    font-weight: 700;
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const isProduction = api.context.props.experienceProperties.environment.value === 'production';
	return {
		event: 'Complete step',
		value: {
			Environment: isProduction ? 'Production' : 'Subproduction',
			Skipped: true,
			Step: 'Store Application Upgrades'
		}
	};
})

